.simple {
  --single: value;
  --multiple: value1 value2;
  --function: foo(bar);
  --url: url(http://foo.com/bar);
  --color: #foo;
  --exponent: 12.6e7;
  --close-comment: */;

  // The whitespace here DOES count as a token and needs to be preserved.
  --empty: ;

  // Single-line comments are not supported in variables.
  --single-line: // (
    );

  // Extra whitespace isn't added.
  --no-extra-whitespace:value;
}

.strings {
  // Strings are tokenized as units, so their contents shouldn't affect anything
  // else.
  --text: "foo";
  --bang: "!";
  --semicolon: ";";
  --square: "][";
  --curly: "}{";
  --parens: ")(";
}

.value-interpolation {
  // Interpolation is the only Sass construct that's supported in custom
  // variables.
  --alone: #{1 + 2};
  --in-list: a #{1 + 2} c;
  --in-ident: foo#{1 + 2}bar;
  --in-string: "foo#{1 + 2}bar";
  --in-uri: uri(foo#{1 + 2}bar);
}

.simple-value {
  // A custom property at the end of a style rule doesn't need a semicolon.
  --without-semicolon: value
}

.bracketed-value {
  --without-semicolon: {
    a: b
  }
}

