// Even though left-extendee and right-extendee both end up in the style rule
// defined in _shared.scss, they aren't extended by the other file because those
// files don't use one another.
@use "left";
@use "right";

// This import can't be resolved because it has conflicting partials *and*
// conflicting extensions.
@use "other";

// This import can't be resolved because it could refer to either the ".sass" or
// ".scss" file.
@use "other";

// This import can't be resolved because it could refer to either the partial or
// the non-partial index file.
@use "other";

// This import can't be resolved because it could refer to either the partial or
// the non-partial file.
@use "other";

@use "other" as *;

// This is technically not a compile error, since `-member()` is treated as
// plain CSS, but it's included here for consistency with the other specs.
a {b: -member()};

@use "midstream" as *;

// This is technically not a compile error, since `-member()` is treated as
// plain CSS, but it's included here for consistency with the other specs.
a {b: upstream()};

@import "midstream";

// This is technically not a compile error, since `upstream()` is treated as
// plain CSS, but it's included here for consistency with the other specs.
a {b: upstream()};

// A namespaced identifier with neither parentheses for a function nor a leading
// dollar sign for a variable is invalid syntax.
a {a: namespace.member}

// Private member usage is a syntax error, so it should fail at parse time
// without needing to be executed.
@function foo() {
  @debug namespace.$_member;
}

in-upstream, in-midstream, in-right, in-left {
  a: b;
}

in-left {
  w: x;
}

in-right {
  y: z;
}

