@use "sass:selector";
// The longest common subsequence is `.c .d .e`, which is longer than `.f g`, so
// `.c .d .e` gets unified while `.f .g` gets duplicated.
a {b: selector.unify(".c .d .e .f .g .s1", ".f .g .c .d .e .s2")}

@use "sass:selector";
// The longest common subsequence is `.c .d`, which is longer than `.e`, so `.c
// .d` gets unified while `.e` gets duplicated.
a {b: selector.unify(".c .d .e .s1", ".e .c .d .s2")}

@use "sass:selector";
// Because neither compound selector containing `.c` is a superselector of the
// other, they aren't unified.
a {b: selector.unify(".c.s1-1 .s1-2", ".c.s2-1 .s2-2")}

@use "sass:selector";
// Even though neither selector containing `#c` is a superselector of the other,
// they're still unified because the selector can't meainingfully contain two
// instances of `#c`.
a {b: selector.unify("#c.s1-1 .s1-2", "#c.s2-1 .s2-2")}

@use "sass:selector";
$result: selector.unify("c d, e f", ".g");
a {
  result: $result;
  structure: $result == ("c" "d.g", "e" "f.g");
}

a {
  result: c d.g, e f.g;
  structure: true;
}

test_cases.expected_output:
a {
  result: c d.g, e f.g;
  structure: true;
}

