@use "sass:color";
a {
  b: color.adjust(
    black,
    $hue: 12,
    $saturation: 24%,
    $lightness: 48%,
    $alpha: 0.7
  );
}

a {
  b: color(srgb none none none);
}

test_cases.expected_output:
a {
  b: color(srgb none none none);
}

