files.content:
@use "sass:color";
// When we weight entirely towards a transparent color, the formula for
// computing the combined alpha would divide by zero, so we just return
// transparent as a special case.
a {b: color.mix(transparent, #0144bf, 100%)}

// "specified" was a method in an earlier draft of CSS Colors 4, but it was
// dropped because it required implementations to lazily normalize hues.
a {b: mix(red, blue, $method: hsl specified hue)}

@use "sass:color";
// An earlier draft of CSS Colors 4 didn't allow some spaces because they were
// redundant with others, but they should be allowed now.
a {b: color.mix(lab(54.3 80.8 69.9), lch(46.3 68 134), $method: display-p3)}

@use "sass:color";
a {
  b: color.mix(
    color(srgb 0.1 0.2 none),
    color(srgb 0.3 0.2 none),
    $method: rec2020
  );
}

@use "sass:color";
a {
  b: color.mix(
    color(srgb none 0.1 0.2),
    color(srgb 0.1 0.2 0.3),
    $method: rec2020
  );
}

@use "sass:color";
a {
  b: color.mix(
    color(srgb 0.1 0.2 0.3),
    color(srgb 0.1 none 0.2),
    $method: rec2020
  );
}

@use "sass:color";
a {
  b: color.mix(
    color(srgb 0.1 0.2 none),
    color(srgb 0.3 0.2 none),
    $method: srgb
  );
}

@use "sass:color";
a {
  b: color.mix(
    color(srgb none 0.1 0.2),
    color(srgb 0.1 0.2 0.3),
    $method: srgb
  );
}

@use "sass:color";
a {
  b: color.mix(
    color(srgb 0.1 0.2 0.3),
    color(srgb 0.1 none 0.2),
    $method: srgb
  );
}

@use "sass:color";
// All channels should be averaged across the two colors.
a {b: color.mix(#91e16f, #0144bf)}

@use "sass:color";
// If two channels have the same values, they should be the same in the output.
a {b: color.mix(#123456, #123456)}

@use "sass:color";
// Each channel becomes the average of 255 and 0, which is 128 = 0xAA.
a {b: color.mix(#ff00ff, #00ff00)}

